import { RendererCanvas } from './base/RendererCanvas';

let PARTICLE_COUNT = 2000;     // 파티클 수
let TRAIL_LENGTH = 10;       // 각 파티클의 꼬리 길이(클수록 길다)
let FADE_ALPHA = 0.06;        // 프레임간 페이드 속도 (작을수록 오래남음)
const SPEED = 1.0;            // 파티클 이동 속도 배율

export class Solution extends RendererCanvas {
	particles
	t = 0.0;
	constructor(id: string) {
		super(document.getElementById(id) as HTMLDivElement);
		// this.ctx.translate(this.ctx.canvas.width * 0.5, this.ctx.canvas.height * 0.5);
		this.clear = () => { return 0 }
		this.init();
	}
	public init() {


		// this.particles = [];
		let lastTime = performance.now();

		const createParticles = (n) => {
			// debugger
			this.particles = new Array(n).fill(0).map(()=> new Particle(window.innerWidth, window.innerHeight, TRAIL_LENGTH));
		}
		const resetParticles = () => {
			createParticles(PARTICLE_COUNT);
		}

		createParticles(PARTICLE_COUNT);


		this.start();
	}
	public render(ctx: CanvasRenderingContext2D): void {
		// const v0 = new Particle(0, 0, 0);
		// v0.render(ctx);

		// const v1 = new Vector3(0, 100, 0);
		// v1.render(ctx);

		// const v2 = new Vector3(100, 0, 0);
		// v2.render(ctx);
		let lastTime = performance.now();
		let now = this.t
		  const dt = (now - lastTime) * 0.06; // dt 스케일: 조정하면 속도감 변함
		lastTime = now;

		// 캔버스를 아주 약하게 덮어 이전을 조금씩 지운다 -> 잔상 지속
		ctx.fillStyle = `rgba(1,4,20,${FADE_ALPHA})`; // 어두운 색의 약한 알파
		ctx.fillRect(0,0,ctx.canvas.width,ctx.canvas.height);

		// 블렌딩을 smoother하게 하기 위해 라인 그리기 전에 합성모드 사용 가능
		ctx.globalCompositeOperation = 'lighter';

		// 각 파티클 업데이트 및 그리기
		for (let p of this.particles) {
			p.step(dt, now);
			p.draw(ctx);
		}

		ctx.globalCompositeOperation = 'source-over';


		this.t += 0.1;
		// console.log(this.t)
	}
}




/* ---------- 간단한 벡터 필드 (노이즈 흉내) ---------- */
/* 실제 기상 데이터로 교체하면 더 정확한 풍형을 얻을 수 있습니다. */
function windField(x, y, t=0) {
  // 여러 주파수의 사인/코사인 조합으로 스웰과 회전 만들어냄
  const nx = x * 0.001;
  const ny = y * 0.001;
  const a =
    Math.sin(nx * 1.3 + t * 0.0005) * 0.8 +
    Math.cos(ny * 0.9 - t * 0.0008) * 0.6 +
    Math.sin((nx+ny) * 0.5 + t * 0.0003) * 0.4;
  // angle과 강도 분리
  const angle = a * Math.PI * 1.25;
  const speed = 0.6 + (Math.sin(nx*2.1 + ny*1.7 + t*0.0007) + 1) * 0.6;
  return { vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed };
}

/* ---------- 파티클 정의 ---------- */
class Particle {
	w = 0
	h = 0
	x = 0
	y = 0
	hue
	alphaBase
	history
	maxHistory
  constructor(w, h, trailLen) {
    this.w = w; this.h = h;
    this.reset(true, trailLen);
  }
  reset(fullRandom=false, trailLen=TRAIL_LENGTH) {
    this.x = Math.random() * this.w;
    this.y = Math.random() * this.h;
    this.history = [];
    this.maxHistory = trailLen;
    // 색감: 랜덤성 부여하되 전체 톤을 녹청 계열로
    const hue = 150 + Math.random()*60; // 150 ~ 210
    this.hue = hue;
    this.alphaBase = 0.9;
  }
  trimHistory(newLen) {
    this.maxHistory = newLen;
    if (this.history.length > newLen) this.history.splice(0, this.history.length - newLen);
  }
  step(dt, t) {
    // 현재 위치를 히스토리에 추가
    this.history.push({x:this.x, y:this.y});
    if (this.history.length > this.maxHistory) this.history.shift();

    const field = windField(this.x, this.y, t);
    this.x += field.vx * SPEED * dt;
    this.y += field.vy * SPEED * dt;

    // 화면 밖이면 재배치(바깥으로 조금 나갔을 때도 자연스럽게)
    if (this.x < -50 || this.x > this.w + 50 || this.y < -50 || this.y > this.h + 50) {
      // 10%의 확률로 화면 외곽에서 들어오게 하고, 그 외엔 랜덤
      if (Math.random() < 0.1) {
        // 가장자리에서 진입
        const edge = Math.floor(Math.random()*4);
        if(edge===0){ this.x = -10; this.y = Math.random()*this.h; }
        if(edge===1){ this.x = this.w+10; this.y = Math.random()*this.h; }
        if(edge===2){ this.y = -10; this.x = Math.random()*this.w; }
        if(edge===3){ this.y = this.h+10; this.x = Math.random()*this.w; }
      } else {
        this.x = Math.random()*this.w;
        this.y = Math.random()*this.h;
      }
      this.history.length = 0;
    }
  }
  draw(ctx) {
    if (this.history.length < 2) return;
    // 그릴 때 history를 따라 점점 투명해지게 그린다
    ctx.beginPath();
    for (let i = 0; i < this.history.length - 1; i++) {
      const p0 = this.history[i];
      const p1 = this.history[i+1];
      // 선분을 바로 그리기 (alpha는 끝쪽이 더 밝음)
      const t = i / (this.history.length - 1);
      const alpha = (t*0.9 + 0.1) * 0.85; // 앞쪽은 약하게, 뒷쪽은 강하게
      ctx.strokeStyle = `hsla(${this.hue}, 80%, 55%, ${alpha})`;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(p0.x, p0.y);
      ctx.lineTo(p1.x, p1.y);
      ctx.stroke();
    }
  }
}
